[Fact]
public async Task AC2_SuppressedTypeGeneratesNoFormatterButStillAnalyzed()
{
    var (diags, exceptions) = await this.RunAnalyzerAsync(SuppressedDuplicateKeys);
    var (generated, genDiags) = await this.RunGeneratorAsync(SuppressedDuplicateKeys);

    Assert.DoesNotContain("SuppressedDto", generated);
    Assert.DoesNotContain(genDiags, d => d.Id == "CS8785"); // generator failure
    Assert.False(HasAnalyzerCrash(diags, exceptions));
    Assert.Contains(diags, d => d.Id == MsgPack00xMessagePackAnalyzer.InvalidMessagePackObjectId);
}

