[Fact]
public async Task AC5_NonSuppressedValidTypeStillGeneratesAndIsClean()
{
    const string source = """
        using MessagePack;

        [MessagePackObject]
        public class NormalDto
        {
            [Key(0)]
            public int A { get; set; }

            [Key(1)]
            public string? B { get; set; }
        }

        [MessagePackObject]
        public class MissingKeyDto
        {
            [Key(0)]
            public int A { get; set; }

            public int B { get; set; }
        }
        """;

    var (diags, exceptions) = await this.RunAnalyzerAsync(source);
    Assert.False(HasAnalyzerCrash(diags, exceptions));

    // Only the missing-key member is flagged.
    Diagnostic single = Assert.Single(diags);
    Assert.Equal(MsgPack00xMessagePackAnalyzer.AttributeMessagePackObjectMembersId, single.Id);

    var (generated, genDiags) = await this.RunGeneratorAsync(source);
    Assert.Contains("NormalDto", generated);
    Assert.DoesNotContain(genDiags, d => d.Id == "CS8785");
}

