using MessagePack.SourceGenerator;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

public class CountersignFinding4
{
    [Fact]
    public void GeneratorDoesNotEmitFormatterThatDropsDuplicateKeyMember()
    {
        const string source = @"
using MessagePack;
[MessagePackObject]
public class Foo
{
    [Key(0)] public string A { get; set; }
    [Key(0)] public string B { get; set; }
}
";
        var tpa = ((string)AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES")!).Split(Path.PathSeparator);
        var refs = tpa.Select(p => (MetadataReference)MetadataReference.CreateFromFile(p)).ToList();
        refs.Add(MetadataReference.CreateFromFile(typeof(MessagePack.MessagePackObjectAttribute).Assembly.Location));
        refs.Add(MetadataReference.CreateFromFile(typeof(MessagePack.MessagePackSerializer).Assembly.Location));

        var compilation = CSharpCompilation.Create(
            "TestAsm",
            new[] { CSharpSyntaxTree.ParseText(source) },
            refs.Distinct(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary));

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(compilation, out _, out var diags);
        var result = driver.GetRunResult();

        var fooFormatters = result.GeneratedTrees
            .Where(t => Path.GetFileName(t.FilePath).Contains("FooFormatter"))
            .Select(t => t.GetText().ToString())
            .ToList();

        string info = $"exceptions: {string.Join(";", result.Results.Select(r => r.Exception?.GetType().Name ?? "none"))}; diags: {string.Join(";", diags.Select(d => d.Id + ":" + d.GetMessage()))}; generated: {string.Join(",", result.GeneratedTrees.Select(t => Path.GetFileName(t.FilePath)))}";

        foreach (var text in fooFormatters)
        {
            // Correct behaviour: a generated formatter must not silently drop member B.
            Assert.True(text.Contains(".B"), "Generated FooFormatter silently omits member B. " + info + "\n" + text);
        }
    }
}
